  _c(373, 84, 1, '後輩[こうはい]が作[つく]ってくれた資料[しりょう]に間違[まちが]いがないか（　）チェックする。', ['濃く', 'きつく', '難しく', 'こまかく'], 3, 'Memeriksa dengan teliti apakah dokumen dari kohai ada salahnya.'),
  _c(374, 84, 2, 'このドラマはおもしろいと聞[き]いていたけど、実際[じっさい]は（　）。', ['つまらなかった', 'おかしかった', 'めずらしかった', 'あかるかった'], 0, 'Drama ini katanya menarik, tapi ternyata membosankan.'),
  _c(375, 84, 3, 'お菓子[かし]を食[た]べ過[す]ぎたせいで、顔[かお]が（　）なった。', ['広く', '丸く', '狭く', '厚く'], 1, 'Karena kebanyakan makan kue, wajah jadi bundar.'),
  _c(376, 84, 4, 'いつも真面目[まじめ]な鈴木[すずき]さんは、（　）ことにお酒[さけ]が大好[だいす]きらしい。', ['得意な', '意外な', '大変な', '相当な'], 1, 'Suzuki-san yang selalu serius, entah kenapa justru sangat suka sake.'),
  _c(377, 84, 5, 'ここは遊園地[ゆうえんち]や水族館[すいぞくかん]がある、とても（　）町[まち]だ。', ['にぎやかな', '平気な', '派手な', '退屈な'], 0, 'Kota ini ramai, ada taman hiburan dan akuarium.'),
  _c(378, 84, 6, '数学[すうがく]は好[す]きだが、（　）計算[けいさん]が少[すこ]し苦手[にがて]だ。', ['確実な', '正常な', '複雑な', '危険な'], 2, 'Suka matematika, tapi perhitungan rumit agak lemah.'),
  _c(379, 84, 7, 'コンビニは24時間[じかん]開[あ]いていて、なんでも売[う]っているので（　）。', ['熱心だ', '便利だ', '上品だ', '新鮮だ'], 1, 'Minimarket buka 24 jam dan jual segalanya, jadi praktis.'),
  _c(380, 84, 8, '仕事[しごと]の後[あと]に映画[えいが]をみに行[い]こうと思[おも]っていたが、残業[ざんぎょう]のせいで（　）。', ['残念だった', '迷惑だった', '不安だった', '無理だった'], 3, 'Ingin nonton setelah kerja, tapi lembur jadi tidak mungkin.'),
  _c(381, 84, 9, '先生[せんせい]の（　）説明[せつめい]のおかげで、難[むずか]しい問題[もんだい]も解[と]けるようになりました。', ['重大な', '可能な', '丁寧な', '高価な'], 2, 'Berkat penjelasan guru yang teliti, soal sulit pun bisa dikerjakan.'),
  _c(382, 85, 1, 'この事件[じけん]について、（　）情報[じょうほう]を知[し]りたい。', ['盛んな', '正直な', '確かな', '単純な'], 2, 'Tentang kasus ini, saya ingin informasi yang pasti.'),
  _c(383, 85, 2, '野菜[やさい]をたくさん食[た]べることは、健康[けんこう]にもダイエットにも（　）だ。', ['実用的', '効果的', '基本的', '全体的'], 1, 'Banyak makan sayur efektif untuk kesehatan dan diet.'),
  _c(384, 85, 3, '恥[は]ずかしがらず、もっと（　）に意見[いけん]を出[だ]し合[あ]いましょう。', ['基礎的', '活動的', '積極的', '一般的'], 2, 'Jangan malu, mari lebih aktif saling menyampaikan pendapat.'),
  _c(385, 85, 4, '日本[にほん]のタクシーのドアは、自分[じぶん]で開[あ]けなくても（　）に開[あ]きます。', ['最終的', '人工的', '具体的', '自動的'], 3, 'Pintu taksi Jepang terbuka otomatis tanpa dibuka sendiri.'),
  _c(386, 85, 5, 'わたしは大学[だいがく]で植物[しょくぶつ]について研究[けんきゅう]したので、農業[のうぎょう]について（　）な知識[ちしき]がある。', ['代表的', '経済的', '数学的', '専門的'], 3, 'Karena meneliti tumbuhan di universitas, punya pengetahuan khusus tentang pertanian.'),
  _c(387, 85, 6, '明日[あした]、みんなに（　）お知[し]らせをする予定[よてい]だ。', ['立派な', '重要な', '地味な', '慎重な'], 1, 'Besok akan menyampaikan pengumuman penting kepada semua.'),
  _c(388, 85, 7, '遠[とお]い場所[ばしょ]に住[す]んでいる恋人[こいびと]と、一年[いちねん]ぶりに（　）会[あ]えた。', ['なかなか', 'いつでも', 'ようやく', 'はじめて'], 2, 'Akhirnya bertemu kekasih yang tinggal jauh, setelah setahun.'),
  _c(389, 85, 8, '（　）雨[あめ]が降[ふ]ったら、海[うみ]ではなくプールに行[い]きましょう。', ['今にも', '確か', 'もし', '一度に'], 2, 'Kalau hujan, pergi ke kolam saja, bukan ke laut.'),
  _c(390, 85, 9, '二時[にじ]までにこの仕事[しごと]が終[お]わるかはわかりませんが、（　）早[はや]く終[お]わらせます。', ['なるべく', '主に', '次第に', 'だいたい'], 0, 'Tidak yakin selesai pukul dua, tapi akan diselesaikan secepat mungkin.'),
  _c(391, 86, 1, 'だめだとわかっていても、（　）お菓子[かし]を食[た]べ過[す]ぎてしまいます。', ['まず', 'きちんと', 'つい', 'だんだん'], 2, 'Meski tahu tidak boleh, tanpa sadar kebanyakan makan kue.'),
  _c(392, 86, 2, 'たくさん勉強[べんきょう]したが、（　）試験[しけん]に合格[ごうかく]するとは限[かぎ]らない。', ['例えば', '必ずしも', '多少', 'いくらでも'], 1, 'Meski banyak belajar, tidak selalu lulus ujian.'),
  _c(393, 86, 3, '支払[しはら]う金額[きんがく]を（　）出[だ]すことができた。', ['そのまま', 'まっすぐ', 'ただ', 'ちょうど'], 3, 'Bisa mengeluarkan uang pas sejumlah yang harus dibayar.'),
  _c(394, 86, 4, '割[わ]れたコップは、危[あぶ]ないので（　）触[さわ]らないでください。', ['先に', '突然', '絶対', '最も'], 2, 'Gelas pecah berbahaya, sama sekali jangan disentuh.'),
  _c(395, 86, 5, '多分[たぶん]その作[つく]り方[かた]で合[あ]っていますが、（　）確認[かくにん]しましょう。', ['次々', '結構', '相当', '一応'], 3, 'Mungkin cara itu sudah benar, tapi mari dicek dulu.'),
  _c(396, 86, 6, 'たくさん見[み]たけど、（　）最初[さいしょ]に行[い]ったお店[みせ]の服[ふく]が欲[ほ]しいな。', ['やっと', 'もちろん', 'やっぱり', 'ずいぶん'], 2, 'Sudah banyak dilihat, tapi tetap ingin baju toko yang pertama.'),
  _c(397, 86, 7, '卒業[そつぎょう]してから一度[いちど]も会[あ]っていなかった佐藤[さとう]さんと（　）駅[えき]で会[あ]った。', ['かなり', '偶然', 'せっかく', '結局'], 1, 'Bertemu Sato-san di stasiun secara kebetulan, setelah lama tidak ketemu.'),
  _c(398, 86, 8, '普段[ふだん]はお酒[さけ]を飲[の]まないが、（　）飲[の]むとおいしく感[かん]じる。', ['すぐに', 'あまり', 'もっと', 'たまに'], 3, 'Biasanya tidak minum sake, tapi kadang diminum terasa enak.'),
  _c(399, 86, 9, '大学生[だいがくせい]になってから、（　）実家[じっか]に帰[かえ]っていない。', ['まるで', '時々', 'しばらく', 'たいてい'], 2, 'Sejak jadi mahasiswa, sudah beberapa lama tidak pulang kampung.'),
  _c(400, 87, 1, '本当[ほんとう]はどう思[おも]っているのか、（　）言[い]ってください。', ['そっくり', 'はっきり', 'てっきり', 'きっかり'], 1, 'Tolong katakan dengan jelas apa yang benar-benar dipikirkan.'),
  _c(401, 87, 2, '今日[きょう]は時間[じかん]がないから、また今度[こんど]（　）話[はな]しましょう。', ['ぐっすり', 'さっと', 'そっと', 'ゆっくり'], 3, 'Hari ini tidak ada waktu, lain kali bicara dengan santai.'),
  _c(402, 87, 3, 'まだ本[ほん]を読[よ]みたいけど、明日[あした]も早[はや]いし（　）寝[ね]よう。', ['ころころ', 'ごろころ', 'そろそろ', 'のろのろ'], 2, 'Masih ingin baca, tapi besok pagi, jadi sudah waktunya tidur.'),
  _c(403, 87, 4, '坂井[さかい]さんはアメリカに留学[りゅうがく]していたので、英語[えいご]が（　）話[はな]せます。', ['こんこん', 'うろうろ', 'ぺらぺら', 'べらべら'], 2, 'Sakai-san pernah studi di Amerika, jadi bahasa Inggrisnya fasih.'),
  _c(404, 87, 5, '（　）して、大事[だいじ]な資料[しりょう]を家[いえ]に忘[わす]れてきてしまった。', ['すっかり', 'びっくり', 'きっちり', 'うっかり'], 3, 'Tidak sengaja, dokumen penting tertinggal di rumah.'),
  _c(405, 87, 6, 'この皿[さら]は大切[たいせつ]なものだから、落[お]とさないように（　）持[も]っていてね。', ['すっと', 'ぴったり', 'しっかり', 'そっと'], 2, 'Piring ini berharga, pegang dengan kuat agar tidak jatuh.'),
  _c(406, 87, 7, '暑[あつ]い中[なか]一時間[いちじかん]も山[やま]を歩[ある]いたので、のどが（　）だ。', ['がらがら', 'ざらざら', 'さらさら', 'からから'], 3, 'Berjalan di gunung sejam dalam panas, tenggorokan kering.'),
  _c(407, 87, 8, '朝[あさ]から何[なに]も食[た]べていないので、お腹[なか]が（　）だ。', ['どきどき', 'ぺろぺろ', 'いらいら', 'ぺこぺこ'], 3, 'Dari pagi belum makan, jadi perut lapar.'),
  _c(408, 87, 9, '家[いえ]に着[つ]いたとたん、仕事[しごと]の疲[つか]れが（　）出[で]てきた。', ['どっと', 'ぎっしり', 'さっぱり', 'じっと'], 0, 'Begitu sampai rumah, lelah kerja datang sekaligus.'),
  _c(409, 88, 1, '来月[らいげつ]行[おこな]われる、マラソン大会[たいかい]の（　）を考[かんが]える。', ['エネルギー', 'ケース', 'コース', 'サンプル'], 2, 'Memikirkan rute lomba maraton bulan depan.'),
  _c(410, 88, 2, '山下[やました]さんは、性格[せいかく]が明[あか]るく（　）を取[と]ることが得意[とくい]です。', ['アイデア', 'コミュニケーション', 'マナー', 'メッセージ'], 1, 'Yamashita-san ceria dan pandai berkomunikasi.'),
  _c(411, 88, 3, '興味[きょうみ]のある会社[かいしゃ]のホームページに（　）する。', ['インタビュー', 'アクセス', 'ファックス', 'チェックイン'], 1, 'Mengakses situs perusahaan yang diminati.'),
  _c(412, 88, 4, 'りんごを買[か]いに行[い]ったら、店員[てんいん]さんが（　）で一つ多[おお]く入[い]れてくれた。', ['サービス', 'センター', 'ベランダ', 'ヒント'], 0, 'Saat beli apel, pelayan memberi satu extra sebagai layanan.'),
  _c(413, 88, 5, '今[いま]まで一度[いちど]もやったことがなかったサッカーに（　）する。', ['トレーニング', 'アップ', 'チャレンジ', 'ダビング'], 2, 'Mencoba sepak bola yang belum pernah dilakukan.'),
  _c(414, 88, 6, '会社[かいしゃ]でビジネスの（　）を教[おし]える。', ['マナー', 'サイズ', 'レシピ', 'メニュー'], 0, 'Mengajarkan etiket bisnis di perusahaan.'),
  _c(415, 88, 7, '急[きゅう]に用事[ようじ]ができてしまい、仕方[しかた]なく明日[あした]の予定[よてい]を（　）した。', ['アナウンス', 'リサイクル', 'キャンセル', 'ストップ'], 2, 'Tiba-tiba ada urusan, terpaksa membatalkan rencana besok.'),
  _c(416, 88, 8, '資料[しりょう]を読[よ]んだら、最後[さいご]に（　）をお願[ねが]いします。', ['リスト', 'サイン', 'デザイン', 'テキスト'], 1, 'Setelah membaca dokumen, mohon tanda tangan di akhir.'),
  _c(417, 88, 9, '二[に]か月[げつ]前[まえ]に買[か]ったペンの（　）がもうなくなってしまいました。', ['ソース', 'エンジン', 'インク', 'ペンキ'], 2, 'Tinta pena yang dibeli dua bulan lalu sudah habis.'),
];
